# Build Tutte-Coxeter via LCF notation manually
# LCF: [-13,-9,7,-7,9,13] repeated 5 times on 30 vertices
n = 30
lcf = [-13,-9,7,-7,9,13]
edges = set()
# Hamilton cycle
for i in range(n):
    a, b = i, (i+1) % n
    edges.add((min(a,b), max(a,b)))
# LCF chords
for i in range(n):
    jump = lcf[i % len(lcf)]
    j = (i + jump) % n
    edges.add((min(i,j), max(i,j)))

print("edges:", len(edges))

# Build adjacency
adj = {i: set() for i in range(n)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)
print("degrees:", [len(adj[i]) for i in range(n)])

# Compute girth
from collections import deque
def girth():
    g = float('inf')
    for s in range(n):
        dist = {s:0}
        parent = {s:-1}
        q = deque([s])
        while q:
            u = q.popleft()
            for w in adj[u]:
                if w not in dist:
                    dist[w] = dist[u]+1
                    parent[w] = u
                    q.append(w)
                elif parent[u] != w and dist[w] >= dist[u]:
                    g = min(g, dist[u]+dist[w]+1)
    return g
print("girth:", girth())

# Bipartite check -> 2-colorable -> 3-colorable
color = {0:0}
q = deque([0])
ok = True
while q:
    u = q.popleft()
    for w in adj[u]:
        if w not in color:
            color[w] = 1 - color[u]
            q.append(w)
        elif color[w] == color[u]:
            ok = False
print("bipartite:", ok)
print(sorted(edges))
